#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, mod;
    cin >> n >> mod;

    vector<long long> mem = {0, 1};
    long long su = 1;

    auto add = [&](long long a, long long b) {
        return (a + b) % mod;
    };

    for (int i = 2; i <= n; ++i) {
        int sq = (int)floor(sqrt(i)) + 1;
        long long cur = su;

        for (int f = 2; f < sq; ++f) {
            cur = add(cur, mem[i / f]);
        }

        int be = i;
        for (int j = 1; j <= i / sq; ++j) {
            int nxt = i / (j + 1);
            long long temp = (long long)(be - nxt);
            long long mult_val = (temp % mod + mod) % mod; // ensure non-negative
            long long add_val = (mult_val * mem[j]) % mod;
            cur = add(cur, add_val);
            be = nxt;
        }

        su = add(su, cur);
        mem.push_back(cur);
    }

    cout << mem.back() << "\n";

    return 0;
}
